double blep(double t,double dt){if(t<dt){t/=dt;return t+t-t*t-1;}if(t>1-dt){t=(t-1)/dt;return t*t+t+t+1;}return 0;}
double oscillator(int type,double p,double dt){if(type==0)return sin(2*PI*p);if(type==1)return 2*p-1-blep(p,dt);if(type==2){double q=p+.5;if(q>=1)q-=1;return (p<.5?1.:-1.)+blep(p,dt)-blep(q,dt);}return 2*fabs(2*p-1)-1;}

